import torch

_DTYPES = {
    "float16": torch.float16,
    "float32": torch.float32,
    "float64": torch.float64,
    "bfloat16": torch.bfloat16,
}


def _to_dtype(name):
    if isinstance(name, torch.dtype):
        return name
    return _DTYPES.get(str(name), torch.float32)


def gen_inputs(ctx, device):
    # Reproduce the pytest/benchmark input distribution exactly:
    # torch.rand(shape, dtype) -> uniform [0,1) probabilities for bernoulli.
    shape = ctx["input__shape"]
    dtype = _to_dtype(ctx["input__dtype"])
    return {"input": torch.rand(shape, dtype=dtype, device=device)}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    # Stochastic op: cannot compare elementwise. Mirror the pytest checks:
    # (1) all outputs are 0 or 1; (2) output mean approximates input-probability mean.
    sol = sol_outputs[0].detach().to("cpu").float()
    is01 = bool(((sol == 0) | (sol == 1)).all().item())
    if not is01:
        return {"passed": False, "message": "output contains values other than 0 or 1", "metrics": {}}
    inp = inputs[0].detach().to("cpu").float()
    expected_mean = inp.mean().item()
    actual_mean = sol.mean().item()
    ok = abs(actual_mean - expected_mean) < 0.1
    return {
        "passed": bool(ok),
        "message": "" if ok else f"mean {actual_mean} vs expected {expected_mean}",
        "metrics": {"expected_mean": expected_mean, "actual_mean": actual_mean},
    }


def run(input):
    return torch.bernoulli(input)
